import math

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = lcm(result, numbers[i])
    return result

def calculate_x_k(k, n):
    if n == 0: return 1
    return list_lcm(range(k, k + n))

def test_n(n):
    results = {}
    print(f"--- Testing n = {n} ---")

    # Test k=1
    k = 1
    x_k = calculate_x_k(k, n)
    x_k_plus_1 = calculate_x_k(k + 1, n)
    print(f"k={k}: x_k={x_k}, x_{k+1}={x_k_plus_1}. Increasing: {x_k_plus_1 > x_k}")
    results[k] = (x_k, x_k_plus_1)

    # Test k=2 (if n >= 2)
    if n >= 2:
        k = 2
        x_k = calculate_x_k(k, n)
        x_k_plus_1 = calculate_x_k(k + 1, n)
        print(f"k={k}: x_k={x_k}, x_{k+1}={x_k_plus_1}. Increasing: {x_k_plus_1 > x_k}")
        results[k] = (x_k, x_k_plus_1)

    # Test k=3 (if n >= 3)
    if n >= 3:
        k = 3
        x_k = calculate_x_k(k, n)
        x_k_plus_1 = calculate_x_k(k + 1, n)
        print(f"k={k}: x_k={x_k}, x_{k+1}={x_k_plus_1}. Increasing: {x_k_plus_1 > x_k}")
        results[k] = (x_k, x_k_plus_1)

    return results

for n in range(1, 6):
    test_n(n)

