import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def multi_lcm(numbers):
    if not numbers:
        return 1
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = lcm(result, numbers[i])
    return result

n = 3

# Check x_5 and x_6
# x_k = lcm(k, k+1, k+2)
k1 = 5
k2 = 6

x_k1 = multi_lcm([k1, k1+1, k1+2])
x_k2 = multi_lcm([k2, k2+1, k2+2])

print(f"For n={n}:")
print(f"x_5 = lcm(5, 6, 7) = {x_k1}")
print(f"x_6 = lcm(6, 7, 8) = {x_k2}")

